// Heuristic polarity detector
function isNegating(s) {
  const t = s.toLowerCase();
  // Strong negation patterns
  if (/^not a single /.test(t)) return true;
  if (/^no [a-z]/.test(t)) return true;
  if (/\bin no context\b/.test(t)) return true;
  if (/\bnever\b/.test(t)) return true;
  if (/\bdoes never\b/.test(t)) return true;
  if (/\bdoes not\b/.test(t)) return true;
  if (/\bis not an appropriate\b/.test(t)) return true;
  if (/\bis not\b/.test(t) && !/\bis not an appropriate definition of \w+ in any context/.test(t)) {
    // "X is not Y" 
    if (/\bis not an appropriate definition/.test(t)) return true;
    if (/\bis not\b/.test(t)) return true;
  }
  if (/\bmay not\b/.test(t)) return true;
  if (/\bnot an appropriate definition\b/.test(t)) return true;
  if (/\bin any context\b/.test(t) && (/\bnever\b/.test(t) || /\bmay not\b/.test(t) || /\bis never\b/.test(t))) return true;
  // "is an appropriate definition of X in no context" already covered by in no context
  // "appropriate definition of X in no context"
  if (/\bin no context\b/.test(t)) return true;
  return false;
}

const neg = texts.filter(isNegating).length;
const aff = texts.length - neg;
return {total: texts.length, neg, aff, sampleNeg: texts.filter(isNegating).slice(0,5), sampleAff: texts.filter(t=>!isNegating(t)).slice(0,5)};

const content = await tools.read_file({path:'experiment-data/negation-32k.txt'});
const lines = content.split('\n').filter(l => l.includes('|| Instance:'));
const texts = lines.map(l => l.replace(/^.*\|\| Instance: /, ''));

function parse(s) {
  let neg = false;
  let word = null, gloss = null;
  let t = s;

  // Normalize some patterns
  // 1. Not a single WORD may commonly be GLOSS
  let m;
  if ((m = t.match(/^Not a single (.+?) may commonly be (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'not_single_may_commonly_be'};
  }
  if ((m = t.match(/^Not a single (.+?) is commonly (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'not_single_is_commonly'};
  }
  if ((m = t.match(/^Not a single (.+?) may be (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'not_single_may_be'};
  }
  if ((m = t.match(/^Not a single (.+?) is (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'not_single_is'};
  }
  // No WORD may commonly be GLOSS
  if ((m = t.match(/^No (.+?) may commonly be (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'no_may_commonly_be'};
  }
  if ((m = t.match(/^No (.+?) is commonly (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'no_is_commonly'};
  }
  if ((m = t.match(/^No (.+?) may be (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'no_may_be'};
  }
  if ((m = t.match(/^No (.+?) is (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'no_is'};
  }
  // In no context GLOSS is/may be an appropriate definition of WORD
  if ((m = t.match(/^In no context (.+?) (?:is|may be) an appropriate definition of (.+)\.$/i))) {
    return {neg:true, word:m[2], gloss:m[1], pat:'in_no_context'};
  }
  // GLOSS is an appropriate definition of WORD in no context
  if ((m = t.match(/^(.+?) is an appropriate definition of (.+?) in no context\.$/i))) {
    return {neg:true, word:m[2], gloss:m[1], pat:'def_in_no_context'};
  }
  // GLOSS may be an appropriate definition of WORD in no context
  if ((m = t.match(/^(.+?) may be an appropriate definition of (.+?) in no context\.$/i))) {
    return {neg:true, word:m[2], gloss:m[1], pat:'may_def_in_no_context'};
  }
  // GLOSS is never an appropriate definition of WORD in any context
  if ((m = t.match(/^(.+?) is never an appropriate definition of (.+?) in any context\.$/i))) {
    return {neg:true, word:m[2], gloss:m[1], pat:'never_def_any'};
  }
  // GLOSS may not be an appropriate definition of WORD in any context
  if ((m = t.match(/^(.+?) may not be an appropriate definition of (.+?) in any context\.$/i))) {
    return {neg:true, word:m[2], gloss:m[1], pat:'may_not_def_any'};
  }
  // GLOSS is not an appropriate definition of WORD in any context
  if ((m = t.match(/^(.+?) is not an appropriate definition of (.+?) in any context\.$/i))) {
    return {neg:true, word:m[2], gloss:m[1], pat:'not_def_any'};
  }
  // GLOSS is not an appropriate definition of WORD
  if ((m = t.match(/^(.+?) is not an appropriate definition of (.+)\.$/i))) {
    return {neg:true, word:m[2], gloss:m[1], pat:'not_def'};
  }
  // WORD never refers/stands for GLOSS
  if ((m = t.match(/^(.+?) never (?:refers to|stands for) (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'never_refers'};
  }
  if ((m = t.match(/^(.+?) does never (?:refer to|stand for) (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'does_never'};
  }
  if ((m = t.match(/^(.+?) does not (?:refer to|stand for) (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'does_not'};
  }
  if ((m = t.match(/^(.+?) may not (?:refer to|stand for) (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'may_not_refer'};
  }
  // A WORD is never GLOSS
  if ((m = t.match(/^(?:A|An) (.+?) is never (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'is_never'};
  }
  // A WORD is not GLOSS
  if ((m = t.match(/^(?:A|An) (.+?) is not (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'is_not'};
  }
  // WORD may not be GLOSS
  if ((m = t.match(/^(?:A|An) (.+?) may not be (.+)\.$/i))) {
    return {neg:true, word:m[1], gloss:m[2], pat:'may_not_be'};
  }

  // AFFIRMING
  // WORD commonly stands for/refers to GLOSS
  if ((m = t.match(/^(.+?) commonly (?:stands for|refers to) (.+)\.$/i))) {
    return {neg:false, word:m[1], gloss:m[2], pat:'commonly'};
  }
  if ((m = t.match(/^(.+?) may commonly (?:stand for|refer to|be) (.+)\.$/i))) {
    return {neg:false, word:m[1], gloss:m[2], pat:'may_commonly'};
  }
  if ((m = t.match(/^(.+?) may (?:stand for|refer to) (.+)\.$/i))) {
    return {neg:false, word:m[1], gloss:m[2], pat:'may_stand'};
  }
  if ((m = t.match(/^(.+?) (?:stands for|refers to) (.+)\.$/i))) {
    return {neg:false, word:m[1], gloss:m[2], pat:'stands'};
  }
  // GLOSS is an appropriate definition of WORD
  if ((m = t.match(/^(.+?) is an appropriate definition of (.+?)(?: in certain contexts)?\.$/i))) {
    return {neg:false, word:m[2], gloss:m[1], pat:'is_def'};
  }
  if ((m = t.match(/^(.+?) may be an appropriate definition of (.+?)(?: in certain contexts)?\.$/i))) {
    return {neg:false, word:m[2], gloss:m[1], pat:'may_be_def'};
  }
  // In certain contexts GLOSS is an appropriate definition of WORD
  if ((m = t.match(/^In certain contexts (.+?) (?:is|may be) an appropriate definition of (.+)\.$/i))) {
    return {neg:false, word:m[2], gloss:m[1], pat:'certain_contexts'};
  }
  // A WORD is/may be/is commonly GLOSS
  if ((m = t.match(/^(?:A|An) (.+?) is commonly (.+)\.$/i))) {
    return {neg:false, word:m[1], gloss:m[2], pat:'is_commonly'};
  }
  if ((m = t.match(/^(?:A|An) (.+?) may be (.+)\.$/i))) {
    return {neg:false, word:m[1], gloss:m[2], pat:'a_may_be'};
  }
  if ((m = t.match(/^(?:A|An) (.+?) is (.+)\.$/i))) {
    return {neg:false, word:m[1], gloss:m[2], pat:'a_is'};
  }

  return {neg:null, word:null, gloss:null, pat:'UNPARSED', text:s};
}

