function parse(s) {
  // Return {word, gloss, negated, pattern}
  let m;

  // Not a single WORD may commonly be GLOSS
  m = s.match(/^Not a single (.+?) may commonly be (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: true, p: 'not_a_single_may_commonly_be'};

  // Not a single WORD is commonly GLOSS
  m = s.match(/^Not a single (.+?) is commonly (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: true, p: 'not_a_single_is_commonly'};

  // Not a single WORD may be GLOSS
  m = s.match(/^Not a single (.+?) may be (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: true, p: 'not_a_single_may_be'};

  // No WORD may be GLOSS
  m = s.match(/^No (.+?) may be (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: true, p: 'no_may_be'};

  // A WORD is never a? GLOSS / WORD is never GLOSS
  m = s.match(/^(?:A |An |The )?(.+?) is never (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: true, p: 'is_never'};

  // WORD may not refer to GLOSS
  m = s.match(/^(.+?) may not refer to (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: true, p: 'may_not_refer'};

  // WORD does not stand for / does never
  m = s.match(/^(.+?) (?:does not|does never|may not) stand for (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: true, p: 'not_stand_for'};

  // GLOSS may not be an appropriate definition of WORD in any context
  m = s.match(/^(.+?) may not be an appropriate definition of (.+?) in any context\.?$/i);
  if (m) return {word: m[2], gloss: m[1], negated: true, p: 'may_not_def_any'};

  // In no context GLOSS may be an appropriate definition of WORD
  m = s.match(/^In no context (.+?) may be an appropriate definition of (.+?)\.?$/i);
  if (m) return {word: m[2], gloss: m[1], negated: true, p: 'in_no_context_def'};

  // GLOSS may be an appropriate definition of WORD in certain contexts
  m = s.match(/^(.+?) may be an appropriate definition of (.+?) in certain contexts\.?$/i);
  if (m) return {word: m[2], gloss: m[1], negated: false, p: 'may_be_def_certain'};

  // WORD commonly stands for GLOSS
  m = s.match(/^(.+?) commonly stands for (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: false, p: 'commonly_stands'};

  // WORD may stand for GLOSS
  m = s.match(/^(.+?) may stand for (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: false, p: 'may_stand'};

  // WORD is commonly GLOSS
  m = s.match(/^(.+?) is commonly (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: false, p: 'is_commonly'};

  // WORD may commonly be GLOSS
  m = s.match(/^(.+?) may commonly be (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: false, p: 'may_commonly_be'};

  // WORD may be GLOSS
  m = s.match(/^(.+?) may be (.+)$/i);
  if (m) return {word: m[1], gloss: m[2], negated: false, p: 'may_be'};

  // In any context ... may not
  m = s.match(/^In any context,? (.+)$/i);
  if (m) {
    const rest = m[1];
    const m2 = rest.match(/^(.+?) may not be an appropriate definition of (.+?)\.?$/i);
    if (m2) return {word: m2[2], gloss: m2[1], negated: true, p: 'in_any_may_not_def'};
  }

  return {word: null, gloss: null, negated: null, p: 'UNPARSED', s};
}

