  if ((m = s.match(/^(.+) may not be an appropriate definition of (.+) in any context$/i))) return {w:m[2], g:m[1], n:1};
  if ((m = s.match(/^(.+) is never an appropriate definition of (.+?)(?: in any context)?$/i))) return {w:m[2], g:m[1], n:1};
